    import random
    import time

    LANGUAGE_WRAPPER = 'Consider all integer triples (x, y, z) with x ≤ y ≤ z and |x|, |y|, |z| ≤ {bound} that satisfy the Diophantine surface\nx^2 + y^2 + z^2 + 3(xy + yz + zx) + {beta}(x + y + z) + 1 = 0,\nand in addition meet the congruence filter x + 2y + 3z ≡ {residue} (mod {modulus}). How many such triples are there?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate parameters for the family:
# Surface: x^2 + y^2 + z^2 + 3(xy+yz+zx) + beta(x+y+z) + 1 = 0
# Filters: x <= y <= z, |x|,|y|,|z| <= bound, and x+2y+3z ≡ residue (mod modulus)
# We choose parameters so that the instance is nontrivial and has a reasonably sized answer.
def count_solutions(beta, bound, modulus, residue):
    B = bound
    cnt = 0
    for x in range(-B, B+1):
        for y in range(max(x, -B), B+1):
            # z from y to B
            for z in range(max(y, -B), B+1):
                if (x + 2*y + 3*z - residue) % modulus != 0:
                    continue
                # compute LHS
                lhs = x*x + y*y + z*z + 3*(x*y + y*z + z*x) + beta*(x + y + z) + 1
                if lhs == 0:
                    cnt += 1
    return cnt
tries = 0
while True:
    tries += 1
    if tries > 200:
        # Fallback: deterministic but still valid
        beta = 5
        bound = 18
        modulus = 5
        residue = 2
        cnt = count_solutions(beta, bound, modulus, residue)
        if 3 <= cnt <= 2000:
            return {"beta": beta, "bound": bound, "modulus": modulus, "residue": residue}
        # else just return anyway
        return {"beta": beta, "bound": bound, "modulus": modulus, "residue": residue}
    # Pick beta in a range that often yields many solutions
    beta = rng.randint(-12, 12)
    # Choose a moderate bound to keep search feasible but nontrivial
    bound = rng.randint(12, 24)
    modulus = rng.randint(2, 7)
    residue = rng.randint(0, modulus - 1)
    cnt = count_solutions(beta, bound, modulus, residue)
    # Enforce difficulty: avoid trivial 0/1 counts and avoid explosion
    if 5 <= cnt <= 1500:
        return {"beta": beta, "bound": bound, "modulus": modulus, "residue": residue}
    # Otherwise retry with new random parameters

