    return (False, None)
# Domain checks
if bound < 1:
    # Bound must be positive
    return (False, None)
if modulus < 2:
    # Modulus must be at least 2
    return (False, None)
if not (0 <= residue < modulus):
    # Residue must be in canonical range
    return (False, None)
# Count solutions exactly by definition
B = bound
cnt = 0
for x in range(-B, B+1):
